#!/usr/bin/env python3
"""rollback_v113.py — gets you back to a fully deployable, fully
working state right now. Reverts BOTH globals.css and HeroSection.tsx
to their pre-Tailwind versions, removes the tailwind packages from
package.json. Reverting just the CSS while leaving HeroSection.tsx
using Tailwind class names would have left the Hero section rendering
completely unstyled, since those class names do nothing without the
Tailwind engine generating CSS for them, this avoids that."""
import base64, json, os, sys

if not os.path.exists("app"):
    sys.exit("run from project root")

FILES = {
    "app/globals.css": "",
    "components/terminal/HeroSection.tsx": "",
}
for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(base64.b64decode(enc).decode("utf-8"))
    print("WRITTEN  " + path + " (reverted)")

with open("package.json", "r", encoding="utf-8") as f:
    pkg = json.load(f)
removed = []
for name in ["tailwindcss", "@tailwindcss/postcss"]:
    if name in pkg.get("devDependencies", {}):
        del pkg["devDependencies"][name]
        removed.append(name)
with open("package.json", "w", encoding="utf-8") as f:
    json.dump(pkg, f, indent=2)
    f.write("\n")
print("package.json: removed " + str(removed if removed else "nothing, already clean"))

if os.path.exists("postcss.config.mjs"):
    os.remove("postcss.config.mjs")
    print("REMOVED  postcss.config.mjs")

print("""
NEXT STEPS:
  rm -rf node_modules package-lock.json
  npm install
  npm run build
  git add -A && git commit -m "revert: roll back tailwind migration to unblock deploys" && git push

This gets you back to a confirmed-working state, the exact same Hero
and theme that were live before this migration attempt. Nothing else
from prior rounds is touched. We pause the Tailwind migration here
and pick it up properly once the real cause is confirmed, not guessed.
""")
